import sys

def is_arithmetic(seq):
    if len(seq) < 2:
        return True
    d = seq[1] - seq[0]
    return all(seq[i] - seq[i-1] == d for i in range(2, len(seq)))

def split_into_ap(n, a):
    for i in range(1, n):
        for j in range(i+1, n):
            ap1 = [a[0], a[i]]
            ap2 = [a[j]]
            remaining = set(a[1:]) - {a[i], a[j]}
            while remaining:
                found = False
                for x in list(remaining):
                    if ap1[-1] + (ap1[1] - ap1[0]) == x:
                        ap1.append(x)
                        remaining.remove(x)
                        found = True
                    elif ap2[-1] + (ap2[1] - ap2[0]) == x:
                        ap2.append(x)
                        remaining.remove(x)
                        found = True
                if not found:
                    break
            if is_arithmetic(ap1) and is_arithmetic(ap2) and len(ap1) > 0 and len(ap2) > 0:
                return ap1, ap2
    return None, None

n = int(input().strip())
a = list(map(int, input().strip().split()))

ap1, ap2 = split_into_ap(n, a)
if ap1 is None or ap2 is None:
    print("No solution")
else:
    print(' '.join(map(str, ap1)))
    print(' '.join(map(str, ap2)))
